import type { ClipboardContent } from '../shared/contracts'
import { invalid, object } from './errors'
import { MAX_DOCUMENT_BYTES } from './files'

// Only the small text-formatting subset generated by our renderer is accepted.
// In particular, RTF objects, fields, file references and embedded binary data
// are never accepted from the renderer or placed on the OS clipboard.
const RTF_CONTROLS = new Set(['rtf', 'ansi', 'ansicpg', 'deff', 'uc', 'fonttbl', 'f', 'fnil', 'fmodern', 'colortbl', 'red', 'green', 'blue', 'pard', 'fs', 'cf', 'b', 'i', 'ul', 'strike', 'li', 'tab', 'par', 'line', 'u'])
const RTF_NUMBERS: Record<string, readonly [number, number]> = {
  rtf: [1, 1], ansicpg: [1252, 1252], deff: [0, 0], uc: [1, 1], f: [0, 1], red: [0, 255], green: [0, 255], blue: [0, 255], fs: [1, 216], cf: [0, 1], li: [0, 10000], u: [-32768, 32767],
  b: [0, 1], i: [0, 1], ul: [0, 1], strike: [0, 1],
}

export function validClipboardRtf(value: string): boolean {
  if (!value.startsWith('{\\rtf1') || !value.endsWith('}')) return false
  let depth = 0
  for (let index = 0; index < value.length; index++) {
    const character = value[index]
    const code = value.charCodeAt(index)
    if (code > 0x7e || (code < 0x20 && character !== '\n' && character !== '\r' && character !== '\t')) return false
    if (character === '{') { if (++depth > 64) return false; continue }
    if (character === '}') { if (--depth < 0 || (depth === 0 && index !== value.length - 1)) return false; continue }
    if (character !== '\\') continue
    const escaped = value[++index]
    if (escaped === '\\' || escaped === '{' || escaped === '}') continue
    if (!escaped || !/[a-z]/i.test(escaped)) return false
    let control = escaped
    while (/[a-z]/i.test(value[index + 1] || '')) control += value[++index]
    control = control.toLowerCase()
    if (!RTF_CONTROLS.has(control)) return false
    let numeric = ''
    if (value[index + 1] === '-') numeric += value[++index]
    while (/\d/.test(value[index + 1] || '')) { numeric += value[++index]; if (numeric.length > 6) return false }
    const bounds = RTF_NUMBERS[control]
    if (numeric) {
      if (!bounds || numeric === '-') return false
      const number = Number(numeric)
      if (number < bounds[0] || number > bounds[1]) return false
    } else if (bounds && !['b', 'i', 'ul', 'strike'].includes(control)) return false
    if (control === 'u' && value[index + 1] !== '?') return false
    if (value[index + 1] === ' ') index++
  }
  return depth === 0
}

export function validateClipboard(value: unknown): ClipboardContent {
  const input = object(value)
  if (typeof input.text !== 'string' || input.text.includes('\0') || Buffer.byteLength(input.text, 'utf8') > MAX_DOCUMENT_BYTES) invalid('剪贴板文本无效或超过 16 MB。')
  if (input.html !== undefined && (typeof input.html !== 'string' || input.html.includes('\0') || Buffer.byteLength(input.html, 'utf8') > MAX_DOCUMENT_BYTES)) invalid('剪贴板 HTML 无效或超过 16 MB。')
  if (input.rtf !== undefined && (typeof input.rtf !== 'string' || Buffer.byteLength(input.rtf, 'utf8') > MAX_DOCUMENT_BYTES || !validClipboardRtf(input.rtf))) invalid('剪贴板 RTF 无效或包含不支持的内容。')
  return { text: input.text, ...(input.html === undefined ? {} : { html: input.html as string }), ...(input.rtf === undefined ? {} : { rtf: input.rtf as string }) }
}
